import { OrdersService } from './orders.service';
import { OrdersRepository } from './orders.repository';
import { PaymentsClient } from '../payments/payments.client';

describe('OrdersService', () => {
  it('places order', async () => {
    const repo = new OrdersRepository(null as any);
    const payments = new PaymentsClient({} as any);
    const service = new OrdersService(repo, payments);
    await service.place({ sku: 'A-1', qty: 1 });
  });
});
